def carry_over(apps, schema_editor):
    """Completed deliveries count as delivered; every row gets its order's number and name; transit becomes driving."""
    Delivery = apps.get_model('deliveries', 'Delivery')
    CourierShift = apps.get_model('deliveries', 'CourierShift')
    for delivery in Delivery.objects.select_related('order'):
        delivery.order_number = delivery.order_id or 0
        delivery.customer_name = (delivery.order.name or '') if delivery.order_id else ''
        if delivery.completed:
            delivery.delivered_at = delivery.eta or delivery.timestamp
        delivery.save()
    CourierShift.objects.exclude(mode__in=['walking', 'bicycling', 'driving']).update(mode='driving')


